func (c VMPPClass) GetRecord(ctx context.Context, sessionID SessionRef, self VMPPRef) (VMPPRecord, error) {
	return callAndConvert(ctx, c.client, "VMPP.get_record", convertVMPPRecordToGo, string(sessionID), string(self))
}
